import os,json,urllib.request,urllib.parse
url=os.environ.get('GALAXY_URL','https://usegalaxy.org').rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
tid='toolshed.g2.bx.psu.edu/repos/devteam/kraken/kraken/1.3.1'
req=urllib.request.Request(url+'/api/tools/'+urllib.parse.quote(tid,safe='')+'/build?'+urllib.parse.urlencode({'history_id':'bbd44e69cb8906b5fea48050679a7a0d'}), headers={'x-api-key':key})
with urllib.request.urlopen(req) as r: data=json.load(r)

def opts_repr(opts):
    if isinstance(opts, list):
        return opts[:20]
    if isinstance(opts, dict):
        if 'hda' in opts: return {k: len(v) if isinstance(v,list) else type(v).__name__ for k,v in opts.items()}
        return opts
    return type(opts).__name__

def walk(inputs, pref=''):
    for inp in inputs or []:
        typ=inp.get('type') or inp.get('model_class')
        name=inp.get('name')
        print(pref+f\"{name} [{typ}] label={inp.get('label','')}\")
        if 'options' in inp:
            print(pref+' options=', json.dumps(opts_repr(inp['options']))[:2000])
        if 'value' in inp and inp.get('model_class') "'!= '"'DataToolParameter':
            print(pref+' value=',repr(inp.get('value'))[:200])
        if inp.get('model_class')=='Conditional':
            for case in inp.get('cases',[]):
                print(pref+f\" case {case.get('value')}\")
                walk(case.get('inputs'), pref+'  ')
        elif inp.get('model_class')=='Repeat':
            walk(inp.get('inputs'), pref+'  ')
        elif inp.get('model_class')=='Section':
            walk(inp.get('inputs'), pref+'  ')
walk(data.get('inputs'))
PY"

